const $=s=>document.querySelector(s), key='ombaliz-futur-v1';let step=0,data={date:new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Paris'}),horizon:'5 ans'},remember=false;try{const saved=localStorage.getItem(key);if(saved){data={...data,...JSON.parse(saved)};remember=true}}catch{}const titles=['Me préparer','Imaginer mon futur','Mes changements','Écrire ma lettre','Mon premier pas','Relire & partager'];
const art=i=>{const shapes=[`<path d="M75 142Q56 105 91 75Q125 91 112 134" fill="#9db69a"/><path d="M110 140Q124 91 150 68Q174 109 145 142" fill="#bdcaaa"/><path d="M71 143h82l-12 35H85z" fill="#cbad8c"/><path d="M114 151V98"/>`,`<circle cx="145" cy="65" r="27" fill="#dbb77a"/><path d="M10 158Q70 68 119 136Q168 74 226 157" fill="#a2b9a5"/><path d="M7 178Q89 109 224 177" fill="#d2d9ba"/><path d="M114 189Q78 166 115 145Q139 126 132 112" stroke="#fffaf0" stroke-width="12"/>`,`<path d="M113 174V61M113 109L73 80M113 130l47-36"/><ellipse cx="72" cy="73" rx="23" ry="12" transform="rotate(30 72 73)" fill="#a4bb9c"/><ellipse cx="157" cy="86" rx="25" ry="13" transform="rotate(-35 157 86)" fill="#b9c9a9"/><ellipse cx="115" cy="57" rx="12" ry="25" fill="#789b82"/><path d="M77 176h75"/>`,`<rect x="51" y="37" width="130" height="145" rx="8" fill="#fffdf4"/><path d="M73 72h76M73 92h66M73 112h70M73 132h42" stroke="#b2beb1"/><path d="M139 145l43-65 14 10-44 64-18 10z" fill="#853c51"/>`,`<path d="M36 180h45v-29h42v-33h43V83h38" stroke="#b0bea1" stroke-width="18"/><path d="M72 126q19-52 71-57" stroke="#853c51" stroke-dasharray="5 8"/><path d="M131 60l14 8-10 14"/>`,`<rect x="35" y="70" width="166" height="105" rx="8" fill="#dce4cf"/><path d="M36 73l82 60 82-60M36 174l62-54M200 174l-61-54" stroke="#789b82"/><path d="M111 62q-23-21-9-32 12-8 17 4 9-13 20-3 14 15-28 31" fill="#853c51"/>`];return `<svg viewBox="0 0 240 210" role="img" aria-label="${['Une plante pour se poser','Un chemin vers un horizon','Une pousse qui se développe','Une feuille et un crayon','Des marches pour avancer','Une enveloppe bienveillante'][i]}"><circle cx="120" cy="108" r="94" fill="#e9eddf"/><g stroke="#446966" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round">${shapes[i]}</g></svg>`};
function field(id,label,type='area',hint=''){return `<label for="${id}">${label}</label>${type==='area'?`<textarea id="${id}" data-key="${id}"></textarea>`:`<input id="${id}" data-key="${id}" type="${type}" ${id==='email'?'autocomplete="email"':id==='phone'?'autocomplete="tel"':''}>`}${hint?`<p class="hint">${hint}</p>`:''}`}
function scale(id,label){return `<label for="${id}">${label} <output id="out-${id}">${data[id]??'À préciser'}</output></label><input class="range" type="range" id="${id}" data-key="${id}" min="0" max="10" value="${data[id]??5}"><div class="ends"><span>0 · Pas du tout</span><span>10 · Tout à fait</span></div><p class="hint">Repère personnel facultatif, sans valeur diagnostique. Déplacez le curseur pour répondre.</p>`}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function save(){try{if(remember){localStorage.setItem(key,JSON.stringify(data));$('#saved').textContent='Brouillon enregistré sur cet appareil.'}else $('#saved').textContent='Réponses conservées pendant cette visite uniquement.'}catch{$('#saved').textContent='Enregistrement indisponible : téléchargez votre PDF avant de quitter.'}}
const attitudeIdeas=[["Envers moi-même", [["Bienveillance envers moi", "Après une erreur, me parler comme à une personne que j’aime plutôt que me dévaloriser."], ["Respect de mes besoins", "M’accorder une pause quand je suis fatigué(e), avant d’être à bout."], ["Patience", "Accepter qu’un changement demande plusieurs essais et reconnaître un petit progrès."], ["Souplesse", "Adapter mon programme à mon énergie du jour au lieu de renoncer si tout n’est pas parfait."], ["Accueil des émotions", "Nommer ce que je ressens et me laisser un moment avant de décider comment agir."], ["Droit à l’imperfection", "Terminer une tâche suffisamment bien, sans la reprendre sans fin."]]], ["Dans mes relations", [["Affirmation de soi", "Exprimer un besoin clairement : « J’ai besoin d’un moment pour réfléchir. »"], ["Limites respectueuses", "Dire non à une demande qui dépasse mes possibilités, sans me justifier longuement."], ["Authenticité", "Partager un avis ou une préférence, même si les autres pensent autrement."], ["Écoute", "Écouter une personne jusqu’au bout et vérifier ce que j’ai compris avant de répondre."], ["Ouverture au soutien", "Demander une aide précise à une personne de confiance au lieu de tout porter seul(e)."], ["Réciprocité", "Faire une place à mes besoins autant qu’à ceux des autres dans une relation."]]], ["Dans mes choix et mes actions", [["Courage progressif", "Essayer une petite action importante pour moi, même en présence d’un peu d’appréhension."], ["Autonomie", "Prendre une petite décision en fonction de mes besoins, sans chercher systématiquement une validation."], ["Curiosité", "Explorer une activité ou poser une question plutôt que supposer que je n’y arriverai pas."], ["Persévérance ajustée", "Reprendre après une interruption, en réduisant l’objectif si nécessaire."], ["Présence", "Consacrer quelques minutes à une activité sans regarder mon téléphone."], ["Créativité", "Chercher une autre manière de faire lorsque la solution habituelle ne me convient pas."]]]];
const strengthIdeas=[["Mes capacités dans le quotidien", [["Sens de l’organisation", "J’ai déjà préparé une démarche, organisé une journée ou découpé une tâche en étapes."], ["Capacité d’apprentissage", "J’ai déjà appris quelque chose avec du temps, des essais ou de l’aide."], ["Capacité d’adaptation", "J’ai déjà ajusté ma façon de faire face à un imprévu."], ["Créativité", "J’ai déjà trouvé une idée ou une solution personnelle à une difficulté."], ["Fiabilité", "J’ai déjà tenu un engagement réaliste ou prévenu lorsque je ne pouvais pas le tenir."], ["Sens pratique", "J’ai déjà trouvé une solution concrète, même modeste, à un problème du quotidien."]]], ["Mes ressources relationnelles", [["Écoute", "J’ai déjà pris le temps de comprendre quelqu’un sans le juger."], ["Empathie", "J’ai déjà remarqué qu’une personne allait mal et tenu compte de ce qu’elle ressentait."], ["Capacité à créer du lien", "J’ai déjà entretenu un échange, proposé un moment ensemble ou repris contact."], ["Capacité à demander de l’aide", "J’ai déjà sollicité une personne ou un professionnel lorsque j’en avais besoin."], ["Coopération", "J’ai déjà contribué à une action commune, même en prenant une petite part."], ["Sens de l’équité", "J’ai déjà cherché une solution qui respecte mes besoins et ceux des autres."]]], ["Mes appuis intérieurs", [["Courage", "J’ai déjà fait une démarche importante malgré une inquiétude."], ["Persévérance", "J’ai déjà repris une activité ou un projet après une difficulté."], ["Lucidité sur moi", "J’ai déjà reconnu une difficulté, une limite ou un besoin."], ["Humour", "J’ai déjà trouvé un peu de légèreté sans nier ce qui était difficile."], ["Sensibilité", "J’ai déjà perçu une nuance, une émotion ou un détail important pour moi."], ["Capacité à prendre soin", "J’ai déjà pris soin de moi, d’une personne, d’un animal ou d’un lieu."]]]];
function ideaPicker(groups,target,label){return `<div class="idea-picker"><p class="hint">${label} Cliquez sur « Ajouter » pour garder une piste dans votre réponse. Vous pouvez ensuite la reformuler ou la retirer.</p>${groups.map(([group,items],g)=>`<details class="idea-group" ${g===0?'open':''}><summary>${group} · ${items.length} pistes</summary><div class="idea-grid">${items.map(([name,example],i)=>`<article class="idea"><h4>${name}</h4><p>${example}</p><button type="button" class="secondary" data-idea-target="${target}" data-group="${g}" data-item="${i}" aria-pressed="false">+ Ajouter : ${name}</button></article>`).join('')}</div></details>`).join('')}</div>`}
function ideaLine(target,g,i){const [name,example]=(target==='qualities'?attitudeIdeas:strengthIdeas)[g][1][i];return name+' : '+example}
function refreshIdeas(){document.querySelectorAll('[data-idea-target]').forEach(b=>{const target=b.dataset.ideaTarget;const [name]=(target==='qualities'?attitudeIdeas:strengthIdeas)[b.dataset.group][1][b.dataset.item];const selected=(data[target]||'').split('\n').includes(ideaLine(target,b.dataset.group,b.dataset.item));b.setAttribute('aria-pressed',String(selected));b.textContent=(selected?'✓ Retirer : ':'+ Ajouter : ')+name})}
function bindIdeas(){document.querySelectorAll('[data-idea-target]').forEach(b=>b.onclick=()=>{const target=b.dataset.ideaTarget,line=ideaLine(target,b.dataset.group,b.dataset.item);const lines=(data[target]||'').split('\n');data[target]=lines.includes(line)?lines.filter(x=>x!==line).join('\n'):[data[target],line].filter(Boolean).join('\n');$('#'+target).value=data[target];refreshIdeas();save();toast('Votre réponse a été mise à jour. Vous pouvez la reformuler avec vos mots.')});refreshIdeas()}

function render(){ $('#steps').innerHTML=titles.map((t,i)=>`<button class="${i===step?'active':''}" ${i===step?'aria-current="step"':''} onclick="go(${i})"><b>${i+1}</b>${t}</button>`).join('');$('#position').textContent=`ÉTAPE 0${step+1} / 06`;$('#progress').style.width=(step+1)/6*100+'%';$('#remember').checked=remember;$('#back').hidden=step===0;$('#next').hidden=step===5;
const headers=[['Un moment pour vous.','Cette lettre est une invitation à imaginer une vie plus proche de vos besoins. Vous pouvez avancer une étape à la fois, sans chercher les mots parfaits.'],['Rencontrer votre moi du futur.','Imaginez une journée ordinaire qui vous fait du bien. Vos difficultés peuvent encore exister : ce qui change, c’est votre façon de les traverser.'],['Ce que je souhaite faire évoluer.','Repérez ce qui vous pèse et ce que vous aimeriez cultiver à la place. Gardez une direction réaliste, à votre portée.'],['Des mots pour votre avenir.','Adressez-vous à vous-même avec chaleur. Votre lettre vous appartient : quelques phrases suffisent pour commencer.'],['Un petit pas dès aujourd’hui.','Reliez votre vision à une action simple et concrète. Vous n’avez pas à tout changer d’un coup.'],['Une lettre à garder près de vous.','Relisez vos mots. Vous pouvez revenir à chaque étape, télécharger votre lettre et choisir de la partager.']];
let body='';if(step===0)body=`<section class="card purpose" aria-labelledby="purpose-title"><span class="eyebrow">COMPRENDRE AVANT DE COMMENCER</span><h2 id="purpose-title">Pourquoi écrire à mon moi du futur ?</h2><p>Quand les difficultés prennent beaucoup de place, il peut devenir difficile de savoir vers quoi avancer. Cette lettre vous propose de vous accorder un temps pour imaginer une vie davantage en accord avec vos besoins et vos valeurs, puis de relier cette direction à un petit changement possible aujourd’hui.</p><p class="note">Votre lettre peut devenir une boussole : une trace de ce qui compte pour vous, à relire et à faire évoluer au fil de votre chemin.</p><h3>À quoi cet exercice peut-il m’aider ?</h3><div class="purpose-grid"><article><h4>Clarifier ce qui compte</h4><p>Mettre des mots sur vos besoins, vos envies et les relations ou activités auxquelles vous souhaitez donner davantage de place.</p></article><article><h4>Élargir votre regard sur vous</h4><p>Explorer qui vous souhaitez devenir, au-delà des difficultés actuelles, en reconnaissant aussi les forces et les soutiens déjà présents.</p></article><article><h4>Vous parler avec bienveillance</h4><p>Formuler des encouragements réalistes, reconnaître vos efforts et vous autoriser à progresser avec des hésitations et des jours plus difficiles.</p></article><article><h4>Donner une direction à vos actions</h4><p>Transformer une aspiration en un premier pas concret, en tenant compte des obstacles et de ce qui peut vous aider.</p></article></div><details class="purpose-detail" open><summary>Quel effet puis-je en attendre ?</summary><p>Vous pourrez peut-être vous sentir plus au clair, plus relié(e) à ce qui compte ou davantage disposé(e) à essayer une petite action. L’effet peut aussi être discret, venir plus tard ou ne pas se faire sentir.</p><p>La lettre sert ici de support de réflexion et de dialogue avec votre thérapeute. Elle ne permet pas, à elle seule, de conclure qu’un schéma a changé ou qu’un trouble est traité.</p></details><details class="purpose-detail"><summary>Comment cet exercice prend-il sens dans mon parcours ?</summary><p>Imaginer permet d’explorer une direction. Écrire vous aide à la préciser et à en garder une trace. Identifier vos ressources, anticiper un obstacle et choisir une petite action permet de relier cette réflexion à votre quotidien. Vous pourrez ajuster cette direction en fonction de votre vécu et de vos possibilités.</p><p>Par exemple : « Je voudrais me sentir davantage respecté(e) » peut devenir « Je souhaite exprimer mes besoins », puis « Cette semaine, je demanderai un temps pour réfléchir avant de répondre à une sollicitation ».</p><p>En séance, votre lettre peut ouvrir une discussion : qu’est-ce qui vous touche ? Qu’est-ce qui paraît possible ou difficile ? De quel soutien auriez-vous besoin ?</p></details><details class="purpose-detail"><summary>Et si imaginer l’avenir me met en difficulté ?</summary><p>Vous pouvez choisir un horizon proche, comme les prochaines semaines, et décrire un moment simplement un peu plus satisfaisant. Votre avenir peut comporter des difficultés et des incertitudes : vous pouvez imaginer davantage de soutien ou une autre manière d’y faire face.</p><p>De la tristesse, un décalage avec votre vie actuelle ou aucune émotion particulière peuvent apparaître. Vous n’avez pas à vous forcer à aller bien. Vous pouvez passer une question, faire une pause ou reprendre avec votre thérapeute.</p></details><p class="purpose-closing">Pour commencer, une seule question suffit : <strong>« Qu’aimerais-je pouvoir vivre un peu plus souvent, et qu’est-ce qui pourrait m’y aider ? »</strong></p></section><div class="card"><h3>Mes informations</h3><p class="hint">Elles figureront sur le PDF si vous les renseignez.</p>${field('name','Prénom ou nom (facultatif)','text')}<div class="grid"><div>${field('email','Adresse e-mail','email')}</div><div>${field('phone','Numéro de téléphone','tel')}</div></div>${field('date','Date de rédaction','date')}</div><div class="note">Installez-vous confortablement. Regardez un point autour de vous et respirez naturellement. Vous pouvez garder les yeux ouverts, passer une question ou faire une pause.</div><div class="card">${scale('before','Je me sens disponible pour cet exercice')}</div>`;
if(step===1)body=`<div class="card"><label for="horizon">À quel horizon souhaitez-vous vous projeter ?</label><select id="horizon" data-key="horizon"><option>6 mois</option><option>1 an</option><option>5 ans</option><option>10 ans</option></select>${field('scene','Où êtes-vous et à quoi ressemble votre journée ?','area','Décrivez un lieu, un rythme, des personnes ou un moment simple.')}${field('feel','Comment vous sentez-vous dans cette vie ?','area','Par exemple : plus libre, en confiance, relié(e), apaisé(e).')}${field('needs','Quels besoins et quelles aspirations ont davantage de place ?')}</div><div class="note">Difficile de visualiser ? Pas besoin de voir une image : écrivez simplement ce que vous aimeriez vivre un peu plus souvent.</div>`;
if(step===2)body=`<div class="card">${field('patterns','Quels fonctionnements souhaitez-vous assouplir ?','area','Par exemple : craindre le rejet, vous dévaloriser, vous effacer ou viser la perfection. Ce sont des pistes de réflexion, pas des diagnostics.')}</div><div class="card"><h3>Les attitudes que je souhaite cultiver</h3><p>Une attitude est une façon d’être ou d’agir que vous aimeriez développer. Choisissez une ou deux pistes pour commencer, sans obligation de tout travailler.</p>${ideaPicker(attitudeIdeas,'qualities','Des exemples pour rendre votre direction plus concrète.')}${field('qualities','Mes attitudes à cultiver, avec mes mots','area','Vous pouvez modifier les exemples ajoutés et préciser : dans quelle situation aimerais-je essayer ?')}</div><div class="card"><h3>Les forces sur lesquelles je peux m’appuyer</h3><p>Une force peut être une capacité déjà utilisée, même rarement, dans une situation simple. Elle n’a pas besoin d’être présente tout le temps.</p><p class="note">Si reconnaître vos forces est difficile : pensez à un petit geste qui vous a aidé, à une difficulté traversée avec du soutien, ou à ce qu’un proche bienveillant reconnaîtrait en vous. Vous pouvez aussi laisser cette partie ouverte pour la séance.</p>${ideaPicker(strengthIdeas,'strengths','Ces pistes ne sont ni un test ni une liste de qualités à posséder.')}${field('strengths','Les forces que je reconnais ou souhaite explorer chez moi')}${field('strengthExample','Un petit exemple où une de ces forces m’a aidé(e)','area','Que s’est-il passé ? Qu’avez-vous fait, même modestement ? Vous pouvez aussi noter « à explorer en séance ».')}${field('strengthUse','Comment cette force pourrait-elle m’aider pour la suite ?','area','Par exemple : utiliser mon sens de l’organisation pour prévoir un petit temps de repos.')}</div><div class="card"><h3>Mes appuis dans les moments difficiles</h3>${field('coping','Comment aimeriez-vous faire face aux moments difficiles ?','area','Par exemple : faire une pause, nommer mon émotion, demander du soutien, reprendre avec un objectif plus petit.')}${field('support','Sur quels soutiens extérieurs puis-je compter ?','area','Une personne de confiance, votre thérapeute, un groupe, un lieu apaisant ou une activité qui vous aide. Vous pouvez garder vos réponses précédentes et les compléter.')}</div>`;
if(step===3)body=`<div class="note">Une lettre de votre moi d’aujourd’hui à votre moi du futur. Reconnaissez vos efforts, décrivez ce qui compte et terminez par des encouragements. Vous n’avez pas à promettre la disparition de toutes vos difficultés.</div><div class="card"><details><summary>Quelques amorces pour m’aider</summary><p>« Cher moi du futur, j’aimerais que tu saches… »<br>« J’espère que tu t’autorises davantage à… »<br>« Même si certains jours sont difficiles, rappelle-toi… »<br>« Aujourd’hui, je choisis de commencer par… »</p></details><div class="actions"><button class="secondary" id="draft">M’aider avec mes réponses</button></div><p class="hint">Crée une trame modifiable à partir de vos mots, sans inventer de progrès.</p><label for="letter">Ma lettre</label><textarea id="letter" data-key="letter" class="letter" placeholder="Cher moi du futur…"></textarea><p class="hint" id="words"></p>${field('kindness','Une phrase bienveillante à me rappeler (facultatif)','area','Que diriez-vous à un proche qui traverse la même chose ?')}</div>`;
if(step===4)body=`<div class="card">${field('wish','Mon souhait prioritaire','area','Une direction importante pour vous et sur laquelle vous pouvez agir.')}${field('benefit','Ce que cela apporterait dans ma vie')}${field('obstacle','L’obstacle que je risque de rencontrer','area','Une pensée, une émotion, une habitude ou une difficulté concrète.')}${field('action','Mon premier petit pas, précis et réalisable')}${field('when','Quand et où vais-je le faire ?','text')}${field('plan','Si cet obstacle apparaît, alors je…','area','Choisissez une réponse précise, suffisamment simple pour être essayée.')}${scale('feasible','Cette action me semble faisable')}<p class="note">Si elle paraît trop difficile, réduisez sa taille ou cherchez un soutien. Tenir compte des contraintes extérieures est aussi important.</p>${field('review','Date à laquelle je souhaite relire ma lettre (facultatif)','date')}</div>`;
if(step===5)body=`<div class="preview" id="letter-preview"></div><div class="card">${scale('after','Après cet exercice, je me sens en lien avec ce qui compte pour moi')}<div id="summary"></div><label class="choice"><input type="checkbox" id="include" ${data.include?'checked':''}> Inclure mes réflexions préparatoires et mon plan d’action dans le PDF</label><p class="hint">Par défaut : uniquement votre lettre, vos coordonnées renseignées et la date.</p><div class="actions"><button id="pdf">↓ Télécharger mon PDF</button><button id="share" class="secondary">Partager le PDF…</button></div><h3>Envoyer à mon thérapeute</h3><p class="hint">Le bouton e-mail ouvre votre messagerie : ajoutez le PDF téléchargé en pièce jointe. Le partage du PDF peut proposer Mail ou WhatsApp, selon votre téléphone.</p><div class="actions"><button id="mail" class="secondary">Préparer un e-mail</button><button id="wa" class="secondary">WhatsApp</button><button id="sms" class="secondary">SMS</button></div><p class="hint">Numéro du thérapeute non renseigné : choisissez son contact dans WhatsApp ou votre application Messages. Un SMS ne peut pas contenir de PDF ; il prépare un message sans votre lettre. Pour le document, utilisez « Partager le PDF… » ou joignez-le manuellement dans WhatsApp.</p><p class="note">Rien n’est envoyé automatiquement. Vérifiez le destinataire et les éléments que vous souhaitez transmettre avant de confirmer.</p></div>`;
$('#content').innerHTML=`<div class="hero"><div><span class="eyebrow">${['PRENDRE LE TEMPS','OUVRIR L’HORIZON','CHOISIR UNE DIRECTION','ÉCRIRE AVEC BIENVEILLANCE','PASSER À L’ACTION','CONSERVER & TRANSMETTRE'][step]}</span><h1>${headers[step][0]}</h1><p class="intro">${headers[step][1]}</p></div>${art(step)}</div>${body}`;
document.querySelectorAll('[data-key]').forEach(el=>{if(el.type!=='range')el.value=data[el.dataset.key]??'';el.addEventListener('input',()=>{data[el.dataset.key]=el.value;const out=$('#out-'+el.dataset.key);if(out)out.textContent=el.value;save();if(el.id==='letter')wordcount();if(el.id==='qualities'||el.id==='strengths')refreshIdeas()})});if(step===2)bindIdeas();if(step===3){$('#draft').onclick=makeDraft;wordcount()}if(step===5){$('#letter-preview').textContent=data.letter||'Votre lettre apparaîtra ici. Revenez à l’étape 4 pour l’écrire.';$('#summary').textContent=data.action?'Mon premier pas : '+data.action:'';$('#include').onchange=e=>{data.include=e.target.checked;save()};$('#pdf').onclick=download;$('#share').onclick=share;$('#mail').onclick=()=>{location.href='mailto:contact@ombaliz.com?subject='+encodeURIComponent('Ma lettre au futur — Ombaliz Thérapie')+'&body='+encodeURIComponent('Bonjour,\n\nJe souhaite vous transmettre ma lettre au futur. Je joins le PDF à ce message.\n\nBien cordialement,\n'+(data.name||''));toast('Pensez à joindre le PDF téléchargé à votre message.')};$('#wa').onclick=()=>{window.open('https://wa.me/?text='+encodeURIComponent('Bonjour, je souhaite vous transmettre ma lettre au futur. Je vais joindre mon PDF à cette conversation.'),'_blank','noopener');toast('Choisissez votre thérapeute puis joignez le PDF dans WhatsApp.')};$('#sms').onclick=()=>location.href='sms:?body='+encodeURIComponent('Bonjour, ma lettre au futur est prête. Quel moyen souhaitez-vous utiliser pour recevoir mon PDF ?')}save()}
function go(i){if(i>step&&step===0&&!valid())return;step=i;render();window.scrollTo({top:0,behavior:'smooth'})}function valid(){for(const id of ['email','phone','date']){const el=$('#'+id);if(el&&!el.checkValidity()){el.reportValidity();return false}}return true}function addQuality(t){data.qualities=[data.qualities,t].filter(Boolean).join(', ');$('#qualities').value=data.qualities;save()}
function makeDraft(){if(data.letter?.trim()&&!confirm('Remplacer votre lettre actuelle par une trame construite avec vos réponses ?'))return;data.letter=`Cher moi du futur,\n\nJe t’écris aujourd’hui en pensant à nous dans ${data.horizon}.\n\n${data.scene?'Voici la vie vers laquelle j’aimerais avancer :\n'+data.scene+'\n\n':''}${data.feel?'J’aimerais me sentir :\n'+data.feel+'\n\n':''}${data.needs?'Ce à quoi je souhaite faire plus de place :\n'+data.needs+'\n\n':''}${data.patterns?'Les fonctionnements que je souhaite assouplir :\n'+data.patterns+'\n\n':''}${data.qualities?'Les attitudes que je souhaite cultiver :\n'+data.qualities+'\n\n':''}${data.coping?'Dans les moments difficiles, j’aimerais :\n'+data.coping+'\n\n':''}${data.strengths?'Les forces sur lesquelles je peux m’appuyer :\n'+data.strengths+'\n\n':''}${data.strengthExample?'Une expérience qui me le rappelle :\n'+data.strengthExample+'\n\n':''}${data.strengthUse?'Pour la suite, je pourrais :\n'+data.strengthUse+'\n\n':''}${data.support?'Je peux m’appuyer sur :\n'+data.support+'\n\n':''}Je souhaite reconnaître chaque petit pas, même imparfait. Je m’autorise à avancer à mon rythme.\n\nAvec bienveillance,\n${data.name||'Moi, aujourd’hui'}`;$('#letter').value=data.letter;wordcount();save()}
function wordcount(){$('#words').textContent=(data.letter?.trim().split(/\s+/).filter(Boolean).length||0)+' mots · aucune longueur imposée'}
async function buildPDF(){if(!data.letter?.trim())throw Error('Écrivez votre lettre à l’étape 4 avant de télécharger votre PDF.');if(!window.jspdf)throw Error('Le module PDF est indisponible. Rechargez la page puis réessayez.');const doc=new jspdf.jsPDF({unit:'mm',format:'a4'});let y=0;const logo=new Image();logo.src='logo.png';await logo.decode();const c=document.createElement('canvas');c.width=logo.naturalWidth;c.height=logo.naturalHeight;c.getContext('2d').drawImage(logo,0,0);const logoData=c.toDataURL('image/png');let pages=0;function page(){if(pages)doc.addPage();pages++;doc.setFillColor(250,248,243);doc.rect(0,0,210,297,'F');doc.addImage(logoData,'PNG',20,12,42,42*logo.naturalHeight/logo.naturalWidth);doc.setDrawColor(205,215,205);doc.line(20,39,190,39);y=51}function text(t,size=11,font='helvetica',color=[42,66,65]){doc.setFont(font,'normal');doc.setFontSize(size);doc.setTextColor(...color);for(const line of doc.splitTextToSize(String(t),166)){if(y>270)page();doc.text(line,22,y);y+=size*.48}y+=4}page();text('Ma lettre au futur',25,'times',[36,78,81]);text('Rédigée le '+(data.date||'Non renseignée')+' · Horizon : '+data.horizon,10);text([data.name,data.email,data.phone].filter(Boolean).join(' | ')||'Coordonnées non renseignées',10);if(data.review)text('À relire le '+data.review,10);y+=4;text(data.letter,12,'times');if(data.kindness){y+=4;text('Ma phrase bienveillante',14,'times');text(data.kindness,12,'times')}if(data.include){page();text('Mes repères pour avancer',22,'times');const fields={scene:'Ma vie future',feel:'Mes émotions souhaitées',needs:'Mes besoins et aspirations',patterns:'Mes fonctionnements à assouplir',qualities:'Les attitudes à cultiver',strengths:'Mes forces à mobiliser',strengthExample:'Une expérience où une force m’a aidé(e)',strengthUse:'Mobiliser mes forces pour la suite',coping:'Traverser les difficultés',support:'Mes ressources',wish:'Mon souhait',benefit:'Le bénéfice attendu',obstacle:'Mon obstacle',action:'Mon premier pas',when:'Quand et où',plan:'Si… alors…',feasible:'Faisabilité (0 à 10)',before:'Disponibilité avant (0 à 10)',after:'Lien avec ce qui compte après (0 à 10)'};for(const [k,label]of Object.entries(fields)){if(data[k]!==undefined&&data[k]!==''){text(label,12,'helvetica',[133,60,81]);text(data[k],11)}}text('Repères personnels, sans valeur diagnostique.',9)}const n=doc.getNumberOfPages();for(let p=1;p<=n;p++){doc.setPage(p);doc.setFont('helvetica');doc.setFontSize(8);doc.setTextColor(100,112,108);doc.text('Ombaliz Thérapie · contact@ombaliz.com · Document personnel',22,286);doc.text(p+' / '+n,181,286)}return doc}
async function download(){try{const d=await buildPDF();d.save('Ma_lettre_au_futur.pdf');toast('Votre PDF a été préparé pour le téléchargement.')}catch(e){toast(e.message)}}async function share(){try{const d=await buildPDF(),file=new File([d.output('blob')],'Ma_lettre_au_futur.pdf',{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Ma lettre au futur'})}else{d.save('Ma_lettre_au_futur.pdf');toast('PDF téléchargé. Joignez-le dans votre messagerie ou WhatsApp.')}}catch(e){if(e.name!=='AbortError')toast(e.message)}}
$('#back').onclick=()=>go(step-1);$('#next').onclick=()=>go(step+1);$('#pause').onclick=()=>$('#rest').showModal();$('#remember').onchange=e=>{remember=e.target.checked;try{if(!remember)localStorage.removeItem(key)}catch{}save()};$('#clear').onclick=()=>{if(confirm('Effacer toutes vos réponses et le brouillon enregistré sur cet appareil ?')){try{localStorage.removeItem(key)}catch{}data={date:new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Paris'}),horizon:'5 ans'};remember=false;step=0;render();toast('Vos réponses ont été effacées. Les PDF déjà téléchargés restent sur votre appareil.')}};render();
